import assert from'node:assert/strict';import path from'node:path';import{readFile,writeFile,rm}from'node:fs/promises';import{chromium}from'playwright';import{parseContent,YAML}from'../../scripts/source-project.mjs';import{run}from'../../engine/pipeline.mjs';import{serveStatic}from'../../engine/static.mjs';
const root=path.resolve('artifacts/platform/events-heldout'),project=path.join(root,'pagination-project'),routes=JSON.parse(await readFile(path.join(project,'routes.json'))),record=routes.find(r=>r.route==='/event/coastal-design-lab/'),file=path.join(project,'content',record.collection,'local-added-event.md'),sourceFile=path.join(project,'content',record.collection,record.slug+'.md'),p=parseContent(await readFile(sourceFile,'utf8'),sourceFile);
let browser,server;try{p.meta.title='Locally Authored Event';p.meta.seo_title=p.meta.title;p.meta.permalink='/event/local-added-event/';p.meta.canonical='http://127.0.0.1:9440'+p.meta.permalink;delete p.meta.wordpress_id;delete p.meta.event.id;p.meta.event.start='2029-03-11 10:00:00';p.meta.event.end='2029-03-13 12:00:00';delete p.meta.event.utc_start;delete p.meta.event.utc_end;await writeFile(file,'---\n'+YAML.stringify(p.meta)+'---\n'+p.body);await run(process.execPath,['scripts/build.mjs'],{cwd:project,timeout:120000});
server=await serveStatic(path.join(project,'output'));browser=await chromium.launch({channel:'chrome'});const page=await browser.newPage();let sourceRequests=0;await page.route('**/*',r=>{if(new URL(r.request().url()).origin!==server.url){sourceRequests++;return r.abort();}return r.continue();});await page.goto(server.url+'/events/list/?calendar-date=2028-01-01&calendar-page=3',{waitUntil:'networkidle'});await page.waitForFunction(()=>document.querySelector('.tribe-events-c-nav__prev')?.dataset.calendarPage==='2');assert.equal(await page.locator('.tribe-events-calendar-list__event-row').count(),1);assert.match(await page.locator('.tribe-events-calendar-list__event-title').textContent(),/Locally Authored Event/);assert.equal(await page.locator('.tribe-events-c-nav__next').isDisabled(),true);assert.match(await page.locator('.tribe-events-c-top-bar__datepicker-button').textContent(),/Upcoming/);await page.goto(server.url+'/events/list/page/3/',{waitUntil:'networkidle'});await page.waitForFunction(()=>document.querySelector('.tribe-events-c-nav__prev')?.dataset.calendarPage==='2');assert.equal(await page.locator('.tribe-events-calendar-list__event-row').count(),1);assert.match(await page.locator('.tribe-events-calendar-list__event-title').textContent(),/Locally Authored Event/);assert.equal(sourceRequests,0);const result={nativeMarkdownAdded:true,contentTemplate:p.meta.content_template,newEventRoute:p.meta.permalink,localThirdPage:true,directNativePage:true,finalPageCount:1,sourceRequests,scope:'Added native event reuses captured detail/card templates; paginated calendar follows authored records'};await writeFile(path.join(root,'pagination-authoring-check.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));}finally{await browser?.close();await server?.close();await rm(file,{force:true});await run(process.execPath,['scripts/build.mjs'],{cwd:project,timeout:120000});}
